
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('sv-SE'), money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:2,maximumFractionDigits:2});
const key='l2one_state_v2', defaults={clients:[],visits:[],orders:[],tasks:[],goals:[],routes:[],prices:[],officeProcesses:[],officeActions:[],officeCommercial:[],officeAdministrative:[],officeRituals:[],officeRoles:[],officeFinance:[],officeBudget:[],officeMonthlyClose:[],cashDays:[],cashEntries:[],user:'Ana Paula',server:'',token:'',mustChangePassword:false,syncAt:'',pending:[]};
let s=Object.assign({},defaults,JSON.parse(localStorage.getItem(key)||'{}')),tab='hoje',syncing=false;
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const stateCode=c=>{let uf=norm(c.state).replace(/\s/g,'');if(uf==='pa'||uf==='para')return'PA';if(uf==='ap'||uf==='amapa')return'AP';return uf?'FORA':''};
