if(tab==='marcas'){let prices=(s.prices||[]).slice().sort((a,b)=>[a.brand,a.state,a.description,a.sku].join('|').localeCompare([b.brand,b.state,b.description,b.sku].join('|'),'pt-BR')),brands=[...new Set(prices.map(p=>p.brand).filter(Boolean))];h=`<div class="page-heading"><div><span class="eyebrow">Catálogo comercial</span><h2>Marcas e preços</h2><p>Consulte os valores oficiais por estado. Todos os preços são exibidos em Real.</p></div></div><div class="cards"><div class="card">Marcas<strong>${brands.length}</strong></div><div class="card">Produtos<strong>${prices.length}</strong></div><div class="card">Tabela PA<strong>${prices.filter(p=>p.state==='PA').length}</strong></div><div class="card">Tabela AP<strong>${prices.filter(p=>p.state==='AP').length}</strong></div></div>${s.user==='Ana Paula'?`<div class="box"><h3>Importar tabela de preços</h3><p class="muted">Uma linha por produto no formato: Marca; SKU; Descrição; UF; Preço. Exemplo: Bruna Tavares; BT001; Batom; PA; 49,90</p><form id="priceImportForm"><textarea name="prices" rows="7" placeholder="Marca;SKU;Descrição;UF;Preço" required></textarea><p><button>Importar e substituir os SKUs informados</button></p></form><form id="priceEditForm" onsubmit="savePrice(event)"></form></div>`:''}<div class="box"><h3>Tabela cadastrada</h3>${prices.length?`<div class="scroll"><table><tr><th>Marca</th><th>SKU</th><th>Produto</th><th>UF</th><th>Preço</th><th>Ações</th></tr>${prices.map(p=>`<tr><td><b>${esc(p.brand)}</b></td><td>${esc(p.sku)}</td><td>${esc(p.description||'—')}</td><td><span class="uf-badge">${esc(p.state)}</span></td><td><b>${money(p.price)}</b></td><td>${s.user==='Ana Paula'?`<button onclick="editPrice('${esc(p.brand+'|'+p.state+'|'+p.sku)}')">Editar</button> <button class="secondary" onclick="deleteEntity('price','${esc(p.brand+'|'+p.state+'|'+p.sku)}')">Excluir</button>`:''}</td></tr>`).join('')}</table></div>`:'Nenhuma tabela de preços foi importada. A administradora pode usar o formulário acima.'}</div>`}
